    "v19": "hw_time_on_air_us"
  },
  "struct_hints": [
    {
      "offset": 32,
      "meaning": "tx descriptor/context length used for duration calculation"
    },
    {
      "offset": 107,
      "meaning": "PHY rate/class parameter passed to mac_duration_calc"
    },
    {
      "offset": 112,
      "meaning": "MPDU count for aggregate transmit duration"
    },
    {
      "offset": 40,
      "meaning": "configuration flag bit7 selects software duration instead of hardware time-on-air"
